CREATE TABLE admins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) UNIQUE NOT NULL, email VARCHAR(254) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, identity_hash CHAR(64) NOT NULL, attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(identity_hash,attempted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE classes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, description TEXT NOT NULL, display_order INT NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE academic_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE admission_enquiries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_name VARCHAR(120) NOT NULL, parent_phone VARCHAR(20) NOT NULL, student_name VARCHAR(120) NOT NULL, class_id BIGINT UNSIGNED NOT NULL, academic_session_id BIGINT UNSIGNED NOT NULL, current_school VARCHAR(200), message TEXT, status ENUM('New','Contacted','Follow-up Required','Visit/Meeting Scheduled','Admitted','Not Interested') NOT NULL DEFAULT 'New', next_follow_up_at DATETIME NULL, duplicate_flag BOOLEAN DEFAULT 0, archived_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(class_id) REFERENCES classes(id), FOREIGN KEY(academic_session_id) REFERENCES academic_sessions(id), INDEX(parent_phone),INDEX(status),INDEX(created_at),INDEX(next_follow_up_at),INDEX(archived_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE enquiry_notes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,enquiry_id BIGINT UNSIGNED NOT NULL,admin_id BIGINT UNSIGNED NOT NULL,note TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(enquiry_id) REFERENCES admission_enquiries(id) ON DELETE CASCADE,FOREIGN KEY(admin_id) REFERENCES admins(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE site_settings (setting_key VARCHAR(80) PRIMARY KEY,setting_value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE site_content (content_key VARCHAR(80) PRIMARY KEY,content_value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE announcements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,body TEXT NOT NULL,is_published BOOLEAN NOT NULL DEFAULT 0,starts_at DATETIME NULL,ends_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
